commands.windows:
# Standalone example: firewall profiles, BitLocker, Defender and AppLocker as text.
# The built-in sensor reports the same as structured fields and escrows BitLocker recovery passwords to the server.
Get-NetFirewallProfile | ForEach-Object { "firewall $($_.Name): enabled=$($_.Enabled) inbound=$($_.DefaultInboundAction)" }
Get-BitLockerVolume -ErrorAction SilentlyContinue | ForEach-Object { "bitlocker $($_.MountPoint): $($_.VolumeStatus) protection=$($_.ProtectionStatus)" }
$s = Get-MpComputerStatus -ErrorAction SilentlyContinue; if ($s) { "defender: realtime=$($s.RealTimeProtectionEnabled) signatures=$($s.AntivirusSignatureLastUpdated)" }
$p = [xml](Get-AppLockerPolicy -Local -Xml); $p.AppLockerPolicy.RuleCollection | ForEach-Object { "applocker $($_.Type): $($_.EnforcementMode)" }
